(n, x) = [int(i) for i in input().split()]
r = [int(i) for i in input().split()]
if n == 1:
	if r[0] > 0:
		print(r[0])
	else:
		print(r[0] / x)
else:
	st = n - 1
	en = n - 1
	sums = [0] * n
	sums[-1] = r[-1]
	s = r[-1]
	while st > 0:
		st -= 1
		if s > 0:
			s += r[st]
		else:
			s = r[st]
			en = st
		sums[st] = s
	print(sum(r) - max(sums) + max(sums) / x)
